insert into public.faqs (id, page, question_nl, answer_nl, question_en, answer_en, is_visible, sort_order) values ('faq-algemeen-regio', 'algemeen', 'In welke regio werken jullie?', 'Wij werken in Flevoland en Noord-Holland, onder andere in Almere, Amsterdam, Amstelveen, Lelystad, Haarlem, het Gooi en Amersfoort.', 'Which region do you work in?', 'We work in Flevoland and North Holland, including Almere, Amsterdam, Amstelveen, Lelystad, Haarlem, the Gooi area and Amersfoort.', true, 10) on conflict (id) do nothing;
insert into public.faqs (id, page, question_nl, answer_nl, question_en, answer_en, is_visible, sort_order) values ('faq-algemeen-calculator', 'algemeen', 'Is de prijs uit de calculator definitief?', 'Nee. De calculator geeft een vrijblijvende vanafprijs voor arbeid en normale bouwmaterialen. De definitieve prijs wordt vastgesteld na een opname op locatie.', 'Is the price from the calculator final?', 'No. The calculator gives a non-binding starting price for labour and standard construction materials. The final price is determined after an on-site assessment.', true, 20) on conflict (id) do nothing;
insert into public.faqs (id, page, question_nl, answer_nl, question_en, answer_en, is_visible, sort_order) values ('faq-algemeen-reactie', 'algemeen', 'Hoe snel hoor ik iets na mijn aanvraag?', 'Wij nemen binnen 24 uur contact met u op.', 'How soon will I hear back after my request?', 'We will contact you within 24 hours.', true, 30) on conflict (id) do nothing;
insert into public.faqs (id, page, question_nl, answer_nl, question_en, answer_en, is_visible, sort_order) values ('faq-badkamer-kosten', 'badkamer', 'Wat kost een badkamerrenovatie?', 'De prijs hangt af van de omvang, het sanitair, de afwerking en het benodigde werk zoals leidingwerk of verlaagde plafonds. Wij geven vooraf een duidelijke offerte op maat.', 'How much does a bathroom renovation cost?', 'The price depends on the scale, sanitary ware, finishing and required work such as plumbing or lowered ceilings. We provide a clear, tailored quote in advance.', true, 10) on conflict (id) do nothing;
insert into public.faqs (id, page, question_nl, answer_nl, question_en, answer_en, is_visible, sort_order) values ('faq-badkamer-duur', 'badkamer', 'Hoe lang duurt een badkamerrenovatie?', 'Voor een complete badkamerrenovatie is vaak een projectduur van enkele weken nodig, afhankelijk van de omvang, materiaalselectie en eventuele technische aanpassingen.', 'How long does a bathroom renovation take?', 'A complete bathroom renovation often takes several weeks, depending on the scope, material selection and any technical alterations.', true, 20) on conflict (id) do nothing;
insert into public.faqs (id, page, question_nl, answer_nl, question_en, answer_en, is_visible, sort_order) values ('faq-badkamer-compleet', 'badkamer', 'Krijg ik een complete badkamer van A tot Z?', 'Ja. Wij verzorgen het volledige traject: sloopwerk, leidingwerk, tegelwerk, sanitair, afwerking en styling, zodat u één aanspreekpunt heeft.', 'Will I receive a complete bathroom from start to finish?', 'Yes. We manage the complete process: demolition, plumbing, tiling, sanitary ware, finishing and styling, so you have one point of contact.', true, 30) on conflict (id) do nothing;
insert into public.faqs (id, page, question_nl, answer_nl, question_en, answer_en, is_visible, sort_order) values ('faq-wc-kosten', 'wc', 'Wat kost een WC-renovatie?', 'De kosten verschillen per keuze aan tegelwerk, sanitair, leidingwerk en afwerking. Wij geven u graag een concrete indicatie op basis van uw ruimte en wensen.', 'How much does a toilet renovation cost?', 'Costs vary according to your choices of tiling, sanitary ware, plumbing and finishing. We are happy to provide a specific estimate based on your room and requirements.', true, 10) on conflict (id) do nothing;
insert into public.faqs (id, page, question_nl, answer_nl, question_en, answer_en, is_visible, sort_order) values ('faq-wc-klein', 'wc', 'Kan ik een kleine WC laten renoveren?', 'Ja. Veel kleine toiletten kunnen prachtig worden opgewaardeerd met slimme materialen, een compacte indeling en een luxe uitstraling zonder grote verbouwing.', 'Can I renovate a small toilet?', 'Yes. Many small toilets can be transformed beautifully with smart materials, a compact layout and a refined look, without major construction work.', true, 20) on conflict (id) do nothing;
insert into public.faqs (id, page, question_nl, answer_nl, question_en, answer_en, is_visible, sort_order) values ('faq-wc-verbouwen', 'wc', 'Doen jullie ook complete toiletverbouwingen?', 'Ja, wij verzorgen ook complete toiletverbouwingen en WC-renovaties, inclusief leidingwerk, afwerking en het plaatsen van sanitair.', 'Do you also carry out complete toilet refurbishments?', 'Yes, we also manage complete toilet refurbishments and renovations, including plumbing, finishing and sanitary-ware installation.', true, 30) on conflict (id) do nothing;
